@GetMapping("/{id}")
public UserResponse find(@PathVariable("id") long id) {
    return userService.find(id);
}

@PostMapping
public UserResponse create(@RequestBody SaveUserRequest request) {
    return userService.create(request);
}

@PutMapping("/{id}")
public UserResponse replace(@PathVariable("id") long id,
                            @RequestBody SaveUserRequest request) {
    return userService.replace(id, request);
}

@DeleteMapping("/{id}")
public void delete(@PathVariable("id") long id) {
    userService.delete(id);
}
